class SaveMigration { static Map<String,dynamic> migrate(dynamic raw){if(raw is! Map)return {'schemaVersion':2};final result=Map<String,dynamic>.from(raw);final version=(result['schemaVersion'] as num?)?.toInt()??0;if(version<1){result.putIfAbsent('inventory',()=>{'backpack':[],'vault':[],'equipped':{}});}if(version<2){result.putIfAbsent('worldEventHistory',()=>[]);result.putIfAbsent('progressionTrack',()=>{'experience':0,'level':1,'skillPoints':0});}result['schemaVersion']=2;return result;} }
